import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from '../api/axios';
import { FaMapMarkerAlt, FaCalendarAlt, FaTrash, FaClipboardList } from 'react-icons/fa';

function Events() {
  const [events, setEvents] = useState([]);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const res = await axios.get('/events');
        setEvents(res.data);
      } catch (err) {
        setError('Failed to fetch events');
      }
    };

    const checkAdmin = () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          const decoded = JSON.parse(atob(token.split('.')[1]));
          if (decoded.role === 'admin') {
            setIsAdmin(true);
          }
        } catch (err) {
          console.error('Token decode error:', err);
        }
      }
    };

    fetchEvents();
    checkAdmin();
  }, []);

  const handleRegister = async (eventId) => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Login required to register for events.');
      return;
    }

    try {
      const res = await axios.post(
        '/registration/register-event',
        { eventId },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      setMessage(res.data.message || 'Registered successfully');
      setError('');
    } catch (err) {
      setMessage('');
      setError(err.response?.data?.message || 'Registration failed');
    }
  };

  const handleDelete = async (eventId) => {
    if (!window.confirm('Are you sure you want to delete this event?')) return;

    try {
      const token = localStorage.getItem('token');
      await axios.delete(`/events/${eventId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setEvents(events.filter((e) => e._id !== eventId));
      setMessage('Event deleted successfully');
      setError('');
    } catch {
      setMessage('');
      setError('Failed to delete event');
    }
  };

  return (
    <div className="min-vh-100 py-5 px-3" style={{
      backgroundImage: `url('https://images.unsplash.com/photo-1524995997946-a1c2e315a42f')`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
    }}>
      <div className="container">
        <h2 className="text-center mb-5 fw-bold display-5 text-white border-bottom pb-2">🎟️ Event Manager Passes</h2>

        {message && <div className="alert alert-success">{message}</div>}
        {error && <div className="alert alert-danger">{error}</div>}

        {events.length === 0 ? (
          <p className="text-center fs-4 text-white">No events found</p>
        ) : (
          <div className="row">
            {events.map((event) => (
              <div key={event._id} className="col-lg-4 col-md-6 mb-4">
                <div className="border border-2 border-dark bg-white rounded shadow-sm p-4 position-relative" style={{ minHeight: '360px' }}>
                  <div className="border-bottom pb-2 mb-3">
                    <h5 className="fw-bold text-uppercase mb-1">{event.title}</h5>
                    <small className="text-muted">Token ID: #{event._id.slice(-6).toUpperCase()}</small>
                  </div>
                  <p className="text-dark mb-2">{event.description}</p>

                  <div className="mb-2">
                    <FaCalendarAlt className="text-primary me-2" />
                    <strong>Date:</strong> {new Date(event.date).toLocaleDateString()}
                  </div>
                  <div className="mb-2">
                    <FaMapMarkerAlt className="text-danger me-2" />
                    <strong>Location:</strong> {event.location}
                  </div>
                  <p className="text-muted">
                    <small>Issued by: {event.createdBy?.name || 'Event Manager Admin'}</small>
                  </p>

                  <div className="d-flex justify-content-between mt-3 gap-2 flex-wrap">
                    <button
                      className="btn btn-dark w-100"
                      onClick={() => handleRegister(event._id)}
                    >
                      🎫 Generate Pass
                    </button>

                    {isAdmin && (
                      <>
                        <button
                          className="btn btn-outline-primary w-100 mt-2"
                          onClick={() => navigate(`/event-registrations/${event._id}`)}
                        >
                          <FaClipboardList className="me-1" /> View Registrations
                        </button>
                        <button
                          className="btn btn-outline-danger w-100 mt-2"
                          onClick={() => handleDelete(event._id)}
                        >
                          <FaTrash className="me-1" /> Delete Event
                        </button>
                      </>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Events;
